-- 本批 105 个来源在 2026 年的全部二十列，预期 20253 行。
SELECT * FROM us_equity_daily WHERE provider='YAHOO' AND trade_date>='2026-01-01' AND trade_date<='2026-10-16' AND symbol IN ('HUIPF', 'HULK', 'HUMDF', 'HUMGF', 'HUML', 'HUMT', 'HUNGF', 'HUNTF', 'HUPHY', 'HUQVF', 'HURRY', 'HUSQF', 'HUTCY', 'HUYTF', 'HVGDF', 'HVII', 'HVLM', 'HVNVY', 'HVRRF', 'HVRRY', 'HWAIF', 'HWAL', 'HWAUF', 'HWDJF', 'HWDJY', 'HWGG', 'HWGLF', 'HWIN', 'HWKDF', 'HWKE', 'HWNI', 'HWSY', 'HWTHF', 'HXBM', 'HXGBF', 'HXGCF', 'HXPLF', 'HXXPY', 'HYBE', 'HYBOF', 'HYDI', 'HYDTF', 'HYEG', 'HYEX', 'HYFXF', 'HYHDF', 'HYHHF', 'HYHY', 'HYLQF', 'HYPAF', 'HYPF', 'HYPMY', 'HYPOF', 'HYPRF', 'HYSNF', 'HYSNY', 'HYSR', 'HYTLF', 'HYTNF', 'HYWI', 'HYWS', 'HZHI', 'HZLIF', 'HZNFF', 'HZNOF', 'HZRGF', 'IAALF', 'IAFNF', 'IAGX', 'IAHL', 'IARLF', 'IAUGF', 'IAUGY', 'IBATF', 'IBDRY', 'IBDSF', 'IBGR', 'IBIDY', 'IBJHF', 'IBKKF', 'IBOGF', 'IBRC', 'IBRLF', 'IBSS', 'IBTN', 'IBWC', 'IBXG', 'IBXS', 'IBXXF', 'ICABF', 'ICABY', 'ICAGY', 'ICBT', 'ICBU', 'ICCO', 'ICDX', 'ICETF', 'ICGSF', 'ICGUF', 'ICHGF', 'ICLD', 'ICLTF', 'ICMFF', 'ICNB', 'ICNM') ORDER BY trade_date,symbol,provider LIMIT 100001;

-- 本批明确时间窗口的逐来源计数，预期 105 行、合计 291220。
SELECT symbol,provider,count() AS rows FROM us_equity_daily WHERE provider='YAHOO' AND trade_date<='2026-10-16' AND ((trade_date>='2006-01-01' AND symbol IN ('HUIPF', 'HULK', 'HUMDF', 'HUMGF', 'HUML', 'HUMT', 'HUNGF', 'HUPHY', 'HUQVF', 'HURRY', 'HUSQF', 'HUTCY', 'HUYTF', 'HVGDF', 'HVII', 'HVLM', 'HVNVY', 'HVRRY', 'HWAIF', 'HWAL', 'HWAUF', 'HWDJF', 'HWDJY', 'HWGG', 'HWGLF', 'HWIN', 'HWKE', 'HWNI', 'HXBM', 'HXGBF', 'HXGCF', 'HXPLF', 'HXXPY', 'HYBE', 'HYBOF', 'HYDI', 'HYDTF', 'HYEG', 'HYEX', 'HYFXF', 'HYHHF', 'HYHY', 'HYLQF', 'HYPAF', 'HYPF', 'HYPMY', 'HYPOF', 'HYPRF', 'HYSNF', 'HYSNY', 'HYSR', 'HYTLF', 'HYTNF', 'HYWI', 'HYWS', 'HZHI', 'HZLIF', 'HZNFF', 'HZNOF', 'HZRGF', 'IAALF', 'IAFNF', 'IAGX', 'IARLF', 'IAUGF', 'IAUGY', 'IBATF', 'IBDRY', 'IBDSF', 'IBGR', 'IBIDY', 'IBJHF', 'IBKKF', 'IBOGF', 'IBRC', 'IBRLF', 'IBTN', 'IBWC', 'IBXG', 'IBXS', 'IBXXF', 'ICABF', 'ICABY', 'ICAGY', 'ICBT', 'ICDX', 'ICETF', 'ICGSF', 'ICGUF', 'ICHGF', 'ICLD', 'ICLTF', 'ICNB')) OR (trade_date>='2021-10-18' AND symbol IN ('HUNTF', 'HVRRF', 'HWKDF', 'HWSY', 'HWTHF', 'HYHDF', 'IAHL', 'IBSS', 'ICBU', 'ICCO', 'ICMFF', 'ICNM'))) GROUP BY symbol,provider ORDER BY symbol,provider LIMIT 100001;

-- 仅验收的十二个五年段，预期 15060 行；不代表原全历史任务成功。
SELECT * FROM us_equity_daily WHERE provider='YAHOO' AND trade_date>='2021-10-18' AND trade_date<='2026-10-16' AND symbol IN ('HUNTF', 'HVRRF', 'HWKDF', 'HWSY', 'HWTHF', 'HYHDF', 'IAHL', 'IBSS', 'ICBU', 'ICCO', 'ICMFF', 'ICNM') ORDER BY trade_date,symbol,provider LIMIT 100001;

-- WAL 需结合原文、Native 和完整键值证明，不独立代表完成。
SELECT name,writerTxn,sequencerTxn,bufferedTxnSize,suspended FROM wal_tables() WHERE name IN ('us_equity_daily','us_equity_intraday') ORDER BY name;
